using System;using System.IO;using System.Linq;using System.Web.Script.Serialization;
class IRImportProbe {
 [STAThread]static int Main(string[] args){try{byte[] source=File.ReadAllBytes(args[0]);var r=IRImport.Read(args[0]);byte[] expected=(byte[])r.Coefficients.Clone();r.Coefficients[0]^=1;var again=IRImport.Read(args[0]);if(!again.Coefficients.SequenceEqual(expected))throw new Exception("Mutable cache");if(!source.SequenceEqual(File.ReadAllBytes(args[0])))throw new Exception("Source modified");string canonical=args[1]+"-canonical.wav";File.WriteAllBytes(canonical,IRImport.WaveBytes(expected));if(!IRImport.Read(canonical).Coefficients.SequenceEqual(expected))throw new Exception("Canonical IR changed on reload");File.WriteAllBytes(args[1]+".f32",expected);File.WriteAllText(args[1]+".json",new JavaScriptSerializer().Serialize(new{passed=true,r.SourceRate,r.SourceChannels,r.SourceFrames,r.UsedFrames,r.TrimmedFrames,r.Converted,r.TailWindow,r.PhaseSafeChannel,r.Summary,source_unchanged=true,cache_isolated=true,canonical_reload_exact=true,hardware_accessed=false}));return 0;}catch(Exception e){File.WriteAllText(args[1]+".json",new JavaScriptSerializer().Serialize(new{passed=false,error=e.ToString(),hardware_accessed=false}));return 1;}}
}
